      sha256 "696eba08d1454ef8bbc7b0ac5d90541d14c5231fd0e72098d48af99e1dc52f0c"
    end
  end
  on_linux do
    on_arm do
      url "https://github.com/qubicsdata/switchboard-releases/releases/download/v2.0.2/switchboard-2.0.2-6bf8246e4ac4-linux-arm64-node.tar.gz"
      sha256 "8cf4ed7a746de36082aa155c547643c013024c4666dfe75a7aeb869d7d832b6d"
    end
    on_intel do
      url "https://github.com/qubicsdata/switchboard-releases/releases/download/v2.0.2/switchboard-2.0.2-6bf8246e4ac4-linux-x64-node.tar.gz"
      sha256 "70c75f13c610cfd16d84c2b0ff7bf77298ce71b370829f3d8d9cbf1f54452a1f"
    end
  end

  skip_clean "libexec"

  def install
    libexec.install Dir["*"]
    (bin/"switchboard").write <<~SH
      #!/bin/sh
      set -eu
      launcher=$0
      case "$launcher" in /*) ;; *) launcher="$PWD/$launcher" ;; esac
      links=0
      while [ -L "$launcher" ]; do
        links=$((links + 1))
        [ "$links" -le 40 ] || { echo 'Switchboard launcher has too many symlinks.' >&2; exit 1; }
        target=$(readlink "$launcher")
        case "$target" in /*) launcher=$target ;; *) launcher="${launcher%/*}/$target" ;; esac
      done
      bin_dir=$(CDPATH= cd -- "${launcher%/*}" && pwd -P)
      case "$bin_dir" in */bin) ;; *) echo 'Invalid Switchboard Homebrew bin directory.' >&2; exit 1 ;; esac
      keg=${bin_dir%/bin}
      formula_dir=${keg%/*}
      case "$formula_dir" in */Cellar/switchboard) ;; *) echo 'Switchboard Homebrew launcher must be installed in its Cellar keg.' >&2; exit 1 ;; esac
      brew_prefix=${formula_dir%/Cellar/switchboard}
      export SWITCHBOARD_LAUNCHER="$brew_prefix/opt/switchboard/bin/switchboard"
      export SWITCHBOARD_DISTRIBUTION=homebrew
      exec "$brew_prefix/opt/switchboard/libexec/bin/switchboard" "$@"
    SH
    (bin/"switchboard").chmod 0755
    (prefix/"INSTALL_HOMEBREW.md").write <<~DOC
      Switchboard 2.0.2 — Homebrew installation

      Current instructions: https://github.com/qubicsdata/switchboard-releases#readme
      Upgrade: brew upgrade qubicsdata/tap/switchboard
      Remove software: brew uninstall switchboard
      Optional login service: brew services start qubicsdata/tap/switchboard
      Stop that service: brew services stop qubicsdata/tap/switchboard

      Homebrew verifies the distribution SHA-256 and ships its pinned Node runtime.

    DOC
  end

  def caveats
    <<~EOS
      Current Homebrew instructions:
        https://github.com/qubicsdata/switchboard-releases#readme
      Upgrade with brew upgrade qubicsdata/tap/switchboard.
      Start a login service only if wanted: brew services start qubicsdata/tap/switchboard.

    EOS
  end

  service do
    run [opt_bin/"switchboard", "service", "run"]
    keep_alive true
    environment_variables PATH: std_service_path_env, SWITCHBOARD_SERVICE_OWNER: "homebrew"
    log_path var/"log/switchboard.log"
    error_log_path var/"log/switchboard.log"
  end

  test do
    ENV["HOME"] = testpath.to_s
    ENV["SWITCHBOARD_HOME"] = (testpath/"home").to_s
    assert_match version.to_s, shell_output("#{bin}/switchboard --version")
    passphrase = testpath/"vault-passphrase"
    passphrase.write "isolated-homebrew-test-passphrase"
    passphrase.chmod 0600
    ENV["SWITCHBOARD_VAULT_PASSPHRASE_FILE"] = passphrase.to_s
    system bin/"switchboard", "--home", testpath/"home", "vault", "init", "--backend", "encrypted-file", "--passphrase-file", passphrase
    system bin/"switchboard", "--home", testpath/"home", "init"
  end
end
